    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AÔB</span> و <span dir=\"ltr\" class=\"expr pt\">BÔD</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">BÔD = 60°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[OC)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AÔB</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">AÔC.</span> نختار الزاويتان المتكاملتان لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: BÔD</span> و <span dir=\"ltr\" class=\"expr pt\">AÔB</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">BÔD = 60°.</span> و لماذا لا مجموع زوايا المثلّث ؟ لأنّها تحتاج مثلّثا، و لا مثلّث في هذا الشّكل."},{"quoi":"القاعدة","math":"زاويتان متكاملتان مجموع قيسيهما <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">BÔD</span> و <span dir=\"ltr\" class=\"expr pt\">AÔB</span> متكاملتان  و  <span dir=\"ltr\" class=\"expr pt\">BÔD = 60°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AÔB = 180° - 60° = 120°</span>"},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[OC)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AÔB</span>  و  <span dir=\"ltr\" class=\"expr pt\">AÔB = 120°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AÔC = 120° : 2 = 60°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">AÔC = 60°</span>"}],
    indice: "احسب أوّلا الزاوية الكاملة، ثمّ اقسمها",
