    enonce: "<span dir=\"ltr\" class=\"expr pt\">ABC</span> مثلّث قائم الزاوية في <span dir=\"ltr\" class=\"expr pt\">A</span> حيث <span dir=\"ltr\" class=\"expr pt\">AB̂C = 30°.</span><br><span dir=\"ltr\" class=\"expr pt\">[BO)</span> و <span dir=\"ltr\" class=\"expr pt\">[CO)</span> منصّفا الزاويتين <span dir=\"ltr\" class=\"expr pt\">AB̂C</span> و <span dir=\"ltr\" class=\"expr pt\">AĈB</span>، و يتقاطعان في <span dir=\"ltr\" class=\"expr pt\">O.</span><br><svg class=\"figure\" direction=\"ltr\" viewBox=\"0 0 310 204\" width=\"310\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"30.0\" y1=\"174.0\" x2=\"280.0\" y2=\"174.0\" stroke=\"#2c3e50\" stroke-width=\"1.6\"/><line x1=\"280.0\" y1=\"174.0\" x2=\"30.0\" y2=\"29.7\" stroke=\"#2c3e50\" stroke-width=\"1.6\"/><line x1=\"30.0\" y1=\"29.7\" x2=\"30.0\" y2=\"174.0\" stroke=\"#2c3e50\" stroke-width=\"1.6\"/><path d=\"M 52.0 174.0 A 22 22 0 0 0 30.0 152.0\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><text x=\"54.7\" y=\"153.3\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c0392b\">90°</text><path d=\"M 260.9 163.0 A 22 22 0 0 0 258.0 174.0\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><text x=\"246.2\" y=\"168.9\" text-anchor=\"middle\" font-size=\"12\" fill=\"#c0392b\">30°</text><path d=\"M 30.0 51.7 A 22 22 0 0 0 49.1 40.7\" fill=\"none\" stroke=\"#c0392b\" stroke-width=\"1.3\"/><circle cx=\"30.0\" cy=\"174.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"17.9\" y=\"185.0\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">A</text><circle cx=\"280.0\" cy=\"174.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"293.5\" y=\"181.9\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">B</text><circle cx=\"30.0\" cy=\"29.7\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"20.8\" y=\"23.1\" text-anchor=\"middle\" font-size=\"13\" font-family=\"serif\" font-style=\"italic\" fill=\"#2c3e50\">C</text></svg><br>أحسب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">BÔC.</span>",
    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 30°</span>  و  <span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب قيس الزاوية <span dir=\"ltr\" class=\"expr pt\">BÔC.</span> نختار المنصّف لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: [BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 30°.</span> و لماذا لا الزاويتان المتقابلتان بالرأس ؟ لأنّها تحتاج زاويتين متقابلتين بالرأس، و لا وجود لهما هنا."},{"quoi":"القاعدة","math":"منصّف زاوية يقسمها إلى زاويتين متقايستين، قيس كلّ منهما نصف قيسها"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[BO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AB̂C</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 30°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 30° : 2 = 15°</span>"},{"quoi":"القاعدة","math":"مجموع قيسات زوايا مثلّث يساوي <span dir=\"ltr\" class=\"expr\">180°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">ABC</span>  و  <span dir=\"ltr\" class=\"expr pt\">BÂC = 90°</span>  و  <span dir=\"ltr\" class=\"expr pt\">AB̂C = 30°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AĈB = 180° - (90° + 30°) = 60°</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">[CO)</span> هو منصّف الزاوية <span dir=\"ltr\" class=\"expr pt\">AĈB</span>  و  <span dir=\"ltr\" class=\"expr pt\">AĈB = 60°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BĈO = 60° : 2 = 30°</span>"},{"quoi":"نطبّق","math":"في المثلّث <span dir=\"ltr\" class=\"expr pt\">OBC</span>  و  <span dir=\"ltr\" class=\"expr pt\">CB̂O = 15°</span>  و  <span dir=\"ltr\" class=\"expr pt\">BĈO = 30°</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">BÔC = 180° - (15° + 30°) = 135°</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">BÔC = 135°</span>"}],
